const T_particles={
  id:'q.particles', ch:'27', title:'Физика элементарных частиц',
  theory:`
  <p>Мы прошли путь от падающего камня до ядра. Остался последний вопрос: а из чего сделано само вещество на самом
  глубоком уровне и какие силы им управляют? Это передний край физики, и здесь особенно важно отделять надёжно
  установленное от гипотез.</p>

  <h3 class="sub">Четыре взаимодействия</h3>
  <p>Всё разнообразие явлений во Вселенной сводится к четырём фундаментальным взаимодействиям:</p>
  <ul>
    <li><strong>Сильное</strong> — самое мощное, но действует лишь на расстояниях порядка размера ядра. Связывает
    кварки и удерживает нуклоны вместе.</li>
    <li><strong>Электромагнитное</strong> — примерно в сто раз слабее сильного, но радиус действия бесконечен.
    Держит атомы, молекулы и всю химию.</li>
    <li><strong>Слабое</strong> — ещё в миллионы раз слабее и с ничтожным радиусом. Именно оно ответственно за
    бета-распад.</li>
    <li><strong>Гравитационное</strong> — невообразимо слабое (слабее сильного в $10^{38}$ раз), но действует на
    всё и никогда не экранируется, поэтому на космических масштабах правит именно оно.</li>
  </ul>

  <h3 class="sub">Слабое взаимодействие</h3>
  <p>Классический пример — распад свободного нейтрона:</p>
  <div class="callout">$n\\rightarrow p+e^-+\\bar{\\nu}$. Нейтрон тяжелее протона на 1,293 МэВ; из них 0,511 МэВ уходит
  на массу рождающегося электрона, а оставшиеся 0,782 МэВ достаются частицам как кинетическая энергия. Свободный
  нейтрон живёт около десяти минут — по меркам микромира это огромный срок, и именно слабость взаимодействия тому
  причиной.</div>
  <p>Отдельная история — <strong>нейтрино</strong>. Эта частица участвует только в слабом взаимодействии, поэтому
  проходит сквозь Землю практически не замечая её. Её существование сначала предсказали «на кончике пера»: без
  неё в бета-распаде не сходились энергия и импульс. Обнаружить нейтрино экспериментально удалось лишь спустя
  четверть века.</p>

  <h3 class="sub">Ускорители</h3>
  <p>Чтобы разглядеть структуру на малых масштабах, нужна короткая волна де Бройля, а значит — большой импульс.
  Поэтому вся физика частиц строится вокруг ускорителей. При больших энергиях частицы движутся почти со скоростью
  света, и работать приходится с релятивистскими формулами: $E=\\gamma mc^2$, причём основная доля энергии идёт уже
  не на разгон, а на рост эффективной массы.</p>
  <p>Магнитное поле заворачивает частицу по окружности радиуса $r=\\dfrac{p}{qB}$ — отсюда и кольцевая форма
  ускорителей, и их гигантские размеры: чем больше энергия, тем больше нужно кольцо.</p>

  <h3 class="sub">Антивещество</h3>
  <p>Дирак, объединяя квантовую механику с теорией относительности, получил уравнение, у которого нашлись решения
  с отрицательной энергией. Он истолковал их как частицы с той же массой, но противоположным зарядом — и вскоре
  <strong>позитрон</strong> действительно нашли в космических лучах.</p>
  <div class="callout">Встречаясь, частица и античастица <strong>аннигилируют</strong>: вещество исчезает целиком,
  превращаясь в излучение. Покоящаяся пара электрон-позитрон даёт два фотона по 0,511 МэВ каждый. Почему именно
  два? Один фотон родиться не может — не сохранился бы импульс.</div>
  <p>Возможен и обратный процесс — <strong>рождение пары</strong>. Фотон превращается в электрон и позитрон, но
  только если его энергии хватает на обе массы покоя: порог составляет $2mc^2=1{,}022$ МэВ. Ниже порога никакого
  рождения не происходит, сколько фотонов ни посылай, — прямая аналогия с красной границей фотоэффекта.</p>

  <h3 class="sub">Лептоны и адроны</h3>
  <p>Все известные частицы делятся на два больших класса. <strong>Лептоны</strong> (электрон, мюон, нейтрино) —
  точечные, никакой внутренней структуры у них не обнаружено. <strong>Адроны</strong> (протон, нейтрон, пионы,
  гипероны) участвуют в сильном взаимодействии и, как выяснилось, составные.</p>

  <h3 class="sub">Кварки</h3>
  <p>К шестидесятым годам открытых адронов стало так много, что говорить об «элементарности» каждого сделалось
  неловко. Гелл-Манн и Цвейг предложили считать их составленными из немногих кварков с дробными зарядами:</p>
  <div class="callout">Кварк $u$ несёт заряд $+\\frac23$, кварк $d$ — заряд $-\\frac13$. Тогда протон — это $uud$,
  что даёт $\\frac23+\\frac23-\\frac13=+1$, а нейтрон — $udd$, что даёт ровно ноль. Частицы из трёх кварков называют
  <strong>барионами</strong>, а из кварка и антикварка — <strong>мезонами</strong>.</div>
  <p>Замечательная особенность: <strong>свободный кварк наблюдать не удаётся</strong>. Чем сильнее растаскиваешь
  кварки, тем сильнее они притягиваются, и энергии в конце концов хватает на рождение новой пары — вместо
  одиночного кварка получаются новые частицы. Это принципиально не похоже ни на что в привычном мире.</p>

  <h3 class="sub">Законы сохранения</h3>
  <p>В мире частиц всё разрешённое законами сохранения рано или поздно происходит, а запрещённое не происходит
  никогда. Кроме знакомых сохранения энергии, импульса и заряда работают и новые: сохранение <strong>барионного
  числа</strong> (поэтому протон не распадается и вещество не исчезает) и сохранение числа лептонов.</p>
  <p>Есть и сюрприз: некоторые привычные симметрии оказались нарушены. Опыт показал, что в слабых взаимодействиях
  <strong>не сохраняется чётность</strong> — природа различает «правое» и «левое». Это стало одним из самых
  неожиданных открытий XX века.</p>

  <h3 class="sub">Что осталось</h3>
  <p>Картина из кварков, лептонов и трёх взаимодействий очень успешна и подтверждена множеством опытов. Но
  открытые вопросы никуда не делись: гравитацию не удалось объединить с остальными взаимодействиями, происхождение
  масс частиц и причина преобладания вещества над антивеществом до конца не поняты. Здесь физика заканчивается
  и начинается работа, которая ещё идёт.</p>`,
  formulas:[
    {tex:'n\\rightarrow p+e^-+\\bar{\\nu}',
     note:'Бета-распад нейтрона — пример слабого взаимодействия.', sim:'forces'},
    {tex:'\\text{сильное}:\\text{эм}:\\text{слабое}:\\text{грав}\\approx1:10^{-2}:10^{-6}:10^{-38}',
     note:'Относительные силы четырёх фундаментальных взаимодействий.', sim:'forces'},
    {tex:'e^++e^-\\rightarrow2\\gamma',
     note:'Аннигиляция: покоящаяся пара даёт два фотона по 0,511 МэВ.', sim:'antimatter'},
    {tex:'E_{\\text{порог}}=2mc^2=1{,}022\\ \\text{МэВ}',
     note:'Порог рождения пары: ниже него фотон не может создать электрон и позитрон.', sim:'antimatter'},
    {tex:'q_u=+\\tfrac23,\\qquad q_d=-\\tfrac13',
     note:'Дробные заряды кварков. Протон $uud$ даёт $+1$, нейтрон $udd$ даёт $0$.', sim:'quarks'},
    {tex:'r=\\dfrac{p}{qB}',
     note:'Радиус кривизны в магнитном поле — отсюда кольцевая форма ускорителей.', sim:'forces'}
  ],
  mistakes:[
    {wrong:'Антивещество — это вещество с отрицательной массой, что-то вроде «минус материи».',
     right:'Масса у антивещества обычная, положительная. Противоположны заряд и некоторые другие квантовые числа.',
     why:'Позитрон весит ровно столько же, сколько электрон, и падает в поле тяжести так же. При встрече с электроном они аннигилируют, превращаясь в два гамма-кванта по 0,511 МэВ, — и вся масса переходит в энергию, а не исчезает в «минусе».'},
    {wrong:'Кварки просто ещё не сумели поймать — не хватает мощности ускорителей.',
     right:'Свободный кварк наблюдать нельзя в принципе: чем сильнее их растаскивают, тем сильнее они притягиваются.',
     why:'На каком-то расстоянии энергии в «струне» между кварками хватает на рождение новой пары, и вместо одиночного кварка получаются новые частицы. Это называется конфайнментом и совершенно не похоже ни на что в привычном мире, где силы с расстоянием слабеют.'},
    {wrong:'Слабое взаимодействие слабее гравитации — оно же самое слабое после неё, судя по названию.',
     right:'На своих масштабах слабое взаимодействие в $10^{32}$ раз сильнее гравитационного. «Слабым» его называют по сравнению с сильным и электромагнитным.',
     why:'Сравнивать силы имеет смысл только на конкретном расстоянии. Слабое взаимодействие вдобавок короткодействующее — оно экспоненциально гаснет уже на $10^{-18}$ м, и на расстоянии в фемтометр действительно оказывается слабее гравитации. Проверьте это в симуляции: она честно показывает, где привычный «учебниковый» порядок сил перестаёт выполняться.'},
    {wrong:'Нейтрино почти не взаимодействует с веществом — значит, его невозможно обнаружить.',
     right:'Его регистрируют, просто для этого нужны детекторы на тысячи тонн и годы наблюдений.',
     why:'Вероятность взаимодействия ничтожна, но её компенсируют количеством: через ладонь каждую секунду проходит около $10^{11}$ солнечных нейтрино. Поставьте достаточно вещества и ждите достаточно долго — счёт пойдёт. Так подтвердили механизм горения Солнца и обнаружили, что нейтрино имеет массу.'},
    {wrong:'Стандартная модель описывает всё — физика элементарных частиц завершена.',
     right:'В неё не входит гравитация, она не объясняет тёмную материю, происхождение масс частиц и преобладание вещества над антивеществом.',
     why:'Стандартная модель невероятно точна в своей области — некоторые её предсказания подтверждены до одиннадцатого знака. Но именно поэтому известно и то, чего она не объясняет. Это не изъян теории, а честно очерченная граница; за ней физика продолжается прямо сейчас.'}
  ],
  links:[
    {to:'q.nuclear', text:'Бета-распад, о котором шла речь в ядерной физике, — прямое проявление слабого взаимодействия. Нейтрино было предсказано именно ради него, за 26 лет до обнаружения.'},
    {to:'mech.grav', text:'Гравитация — самое слабое из четырёх взаимодействий, но единственное без экранировки. Поэтому в мире частиц её не замечают, а во Вселенной правит она.'},
    {to:'mech.energy', text:'Всё, что разрешено законами сохранения, рано или поздно происходит; всё запрещённое — не происходит никогда. Законы сохранения оказались строже любых уравнений движения.'},
    {to:'q.wave', text:'В ускорителе частица одновременно и волна: чем выше энергия, тем короче $\\lambda=h/p$ и тем более мелкие структуры удаётся разглядеть.'}
  ],
  problems:[]
};

