   {to:'em.induction', text:'Правило Ленца — закон сохранения энергии в электромагнитной одежде. Уберите знак минус — получите вечный двигатель.'},
   {to:'q.qm', text:'График $U(x)$ с ямой и барьером переходит в квантовую механику без изменений. Меняется одно: там частица умеет оказаться за барьером.'}
