for(const sec of SECTIONS){
  const r=RECAPS[sec.id]; if(!r) continue;
  sec.topics.push({
    id:sec.id+'.recap', ch:'', title:'Итог раздела', kind:'recap', secId:sec.id,
    theory:r.theory, threads:r.threads||[], quiz:r.quiz||[], links:r.links||[],
    formulas:[], problems:[], mistakes:[]
  });
}
const ALL=SECTIONS.flatMap(s=>s.topics.map(t=>({...t,section:s.title,hard:!!s.hard})));
